class TestLicenseBasedDetector(unittest.TestCase):
    """Test license-based proprietary software detection."""

    def test_detector_initialization(self):
        """Test detector initialization."""
        detector = LicenseBasedDetector()
        self.assertIsNotNone(detector.license_classifier)
        self.assertIsInstance(detector.fallback_proprietary_packages, set)

    def test_proprietary_by_license(self):
        """Test detection of proprietary software by license."""
        detector = LicenseBasedDetector()

        proprietary_package = {
            "name": "test-app",
            "licenses": ["Proprietary", "Commercial"]
        }

        self.assertTrue(detector.is_proprietary(proprietary_package))

    def test_foss_by_license(self):
        """Test detection of FOSS software by license."""
        detector = LicenseBasedDetector()

        foss_package = {
            "name": "test-app", 
            "licenses": ["GPL-3.0", "MIT"]
        }

        self.assertFalse(detector.is_proprietary(foss_package))

    def test_fallback_detection(self):
        """Test fallback detection for packages without license info."""
        detector = LicenseBasedDetector()

        # Known proprietary package without license info
        unknown_proprietary = {
            "name": "google-chrome",
            "licenses": ["unknown"]
        }

        self.assertTrue(detector.is_proprietary(unknown_proprietary))

        # Unknown package without license info (should be considered FOSS)
        unknown_package = {
            "name": "random-foss-app",
            "licenses": ["unknown"]
        }

        self.assertFalse(detector.is_proprietary(unknown_package))

    def test_detection_reason(self):
        """Test detection reason reporting."""
        detector = LicenseBasedDetector()

        proprietary_package = {
            "name": "test-app",
            "licenses": ["Proprietary"]
        }

        reason = detector.get_detection_reason(proprietary_package)
        self.assertIn("Proprietary license", reason)

        foss_package = {
            "name": "test-app",
            "licenses": ["GPL-3.0"]
        }

        reason = detector.get_detection_reason(foss_package)
        self.assertIn("FOSS license", reason)

    def test_foss_apps_not_flagged_by_license(self):
        """Test that FOSS applications with proper licenses are not flagged."""
        detector = LicenseBasedDetector()

        foss_packages = [
            {"name": "firefox", "licenses": ["MPL-2.0"]},
            {"name": "gimp", "licenses": ["GPL-3.0"]},
            {"name": "blender", "licenses": ["GPL-3.0"]},
            {"name": "vlc", "licenses": ["GPL-2.0"]},
            {"name": "libreoffice", "licenses": ["MPL-2.0"]},
            {"name": "audacity", "licenses": ["GPL-2.0"]},
            {"name": "inkscape", "licenses": ["GPL-3.0"]},
            {"name": "krita", "licenses": ["GPL-3.0"]},
        ]

        for package in foss_packages:
            with self.subTest(package=package["name"]):
                self.assertFalse(detector.is_proprietary(package),
                               f"FOSS app '{package['name']}' with license '{package['licenses']}' incorrectly flagged as proprietary")
